-- Function: public.sp_delete_admin_user
-- Backup generated on 2026-11-11 09:05:47

CREATE OR REPLACE PROCEDURE public.sp_delete_admin_user(IN p_user_id uuid)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_is_platform_admin boolean;     v_platform_admin_count integer; BEGIN     -- Check if user is a platform admin     SELECT EXISTS (         SELECT 1 FROM user_roles          WHERE user_id = p_user_id            AND role_id IN (SELECT id FROM roles WHERE name IN ('PlatformAdmin', 'SuperAdmin'))     ) INTO v_is_platform_admin;      IF v_is_platform_admin THEN         SELECT COUNT(DISTINCT ur.user_id) INTO v_platform_admin_count         FROM user_roles ur         JOIN roles r ON ur.role_id = r.id         WHERE r.name IN ('PlatformAdmin', 'SuperAdmin');          IF v_platform_admin_count <= 1 THEN             RAISE EXCEPTION 'Cannot delete the only remaining platform administrator. At least one platform administrator must exist.';         END IF;          -- Remove Platform Admin role from user_roles         DELETE FROM user_roles          WHERE user_id = p_user_id            AND role_id IN (SELECT id FROM roles WHERE name IN ('PlatformAdmin', 'SuperAdmin'));     END IF;      -- Remove organization roles, memberships, and external logins     DELETE FROM user_organization_roles WHERE user_id = p_user_id;     DELETE FROM organization_memberships WHERE user_id = p_user_id;     DELETE FROM user_external_logins WHERE user_id = p_user_id;     DELETE FROM user_roles WHERE user_id = p_user_id;      -- Attempt deletion from users table; fallback to deactivation if referenced by operational foreign keys     BEGIN         DELETE FROM users WHERE id = p_user_id;     EXCEPTION WHEN foreign_key_violation THEN         UPDATE users SET is_active = FALSE, updated_at = NOW() WHERE id = p_user_id;     END; END; $procedure$ ;
